const items = $input.all();
const out = [];
for (const item of items) {
  const b = item.json.body ?? item.json;
  const errores = [];
  const event_id = String(b.event_id ?? '').trim();
  const nombre = String(b.nombre ?? '').trim();
  const email = String(b.email ?? '').trim().toLowerCase();
  let mensaje = String(b.mensaje ?? '').trim();

  if (!event_id) errores.push('event_id es obligatorio');
  if (nombre.length < 2 || nombre.length > 80) errores.push('nombre: 2 a 80 caracteres');
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errores.push('email no valido');

  let truncado = false;
  if (mensaje.length < 10) errores.push('mensaje: minimo 10 caracteres');
  if (mensaje.length > 2000) { mensaje = mensaje.slice(0, 2000); truncado = true; }

  out.push({ json: {
    event_id, nombre, email, mensaje, truncado,
    origen: String(b.origen ?? 'web'),
    valido: errores.length === 0,
    errores,
    recibido_en: new Date().toISOString()
  }});
}
return out;

const item = $input.first();
let raw = String(item.json.choices?.[0]?.message?.content ?? '');
raw = raw.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
const permitidas = ['urgente', 'normal', 'informativo'];
let data = null;
try { data = JSON.parse(raw); } catch (e) { data = null; }
let clasificacion = 'normal', respuesta = '', ia_ok = false;
if (data && permitidas.includes(String(data.clasificacion ?? '').toLowerCase())) {
  clasificacion = String(data.clasificacion).toLowerCase();
  respuesta = String(data.respuesta ?? '');
  ia_ok = true;
}
const uso = item.json.usage ?? {};
